PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entities(entity_id TEXT PRIMARY KEY,kind TEXT,name TEXT,search_text TEXT,inferred INTEGER,unresolved INTEGER,payload TEXT);
CREATE TABLE IF NOT EXISTS sources(source_id TEXT PRIMARY KEY,family TEXT,is_public INTEGER,payload TEXT);
CREATE TABLE IF NOT EXISTS claims(claim_id TEXT PRIMARY KEY,entity_id TEXT,source_id TEXT,canonical_id TEXT,scope TEXT,usable INTEGER,payload TEXT);
CREATE INDEX IF NOT EXISTS claim_entity ON claims(entity_id);
CREATE TABLE IF NOT EXISTS invalidations(output_id TEXT PRIMARY KEY,reason TEXT);
CREATE TABLE IF NOT EXISTS relationships(relationship_id TEXT PRIMARY KEY,entity_id TEXT,route_id TEXT,inferred INTEGER,unresolved INTEGER,invalidated INTEGER,payload TEXT);
CREATE INDEX IF NOT EXISTS relationship_route ON relationships(route_id);
CREATE TABLE IF NOT EXISTS captures(binding_id TEXT PRIMARY KEY,entity_id TEXT,route_id TEXT,inferred INTEGER,invalidated INTEGER,payload TEXT);
CREATE TABLE IF NOT EXISTS routes(route_id TEXT PRIMARY KEY,role TEXT,case_id TEXT,direction TEXT,geometry_id TEXT,geometry_wkb BLOB,length_m REAL,inferred INTEGER,payload TEXT);
CREATE INDEX IF NOT EXISTS route_geometry ON routes(geometry_id);
CREATE TABLE IF NOT EXISTS cells(geometry_id TEXT,cell_index INTEGER,start_m REAL,end_m REAL,length_m REAL,payload TEXT,PRIMARY KEY(geometry_id,cell_index));
CREATE TABLE IF NOT EXISTS scores(geometry_id TEXT PRIMARY KEY,version TEXT,payload TEXT,provenance TEXT);
CREATE TABLE IF NOT EXISTS score_retry_history(attempt_id INTEGER PRIMARY KEY AUTOINCREMENT,geometry_id TEXT,successful INTEGER,payload TEXT);
CREATE TABLE IF NOT EXISTS raster_assets(asset_id TEXT PRIMARY KEY,payload TEXT);
CREATE TABLE IF NOT EXISTS road_links(link_id TEXT PRIMARY KEY,route_id TEXT,entity_id TEXT,source_route_id TEXT,inferred INTEGER,method TEXT,covered_m REAL,intervals TEXT,payload TEXT);
CREATE INDEX IF NOT EXISTS road_link_route ON road_links(route_id);
CREATE TABLE IF NOT EXISTS claim_links(link_id TEXT PRIMARY KEY,route_id TEXT,claim_id TEXT,application TEXT,usable INTEGER,payload TEXT);
CREATE INDEX IF NOT EXISTS claim_link_route ON claim_links(route_id);
CREATE TABLE IF NOT EXISTS place_links(link_id TEXT PRIMARY KEY,route_id TEXT,entity_id TEXT,inferred INTEGER,unresolved INTEGER,relationship_id TEXT,payload TEXT);
CREATE INDEX IF NOT EXISTS place_link_route ON place_links(route_id);
CREATE TABLE IF NOT EXISTS comparisons(case_id TEXT PRIMARY KEY,payload TEXT);
CREATE TABLE IF NOT EXISTS corrections(correction_id TEXT PRIMARY KEY,payload TEXT);
CREATE TABLE IF NOT EXISTS unresolved(item_id TEXT PRIMARY KEY,payload TEXT);
CREATE VIEW IF NOT EXISTS effective_entities AS SELECT * FROM entities e WHERE inferred=0 AND unresolved=0 AND kind!='original_audit_reference' AND NOT EXISTS(SELECT 1 FROM invalidations i WHERE i.output_id=e.entity_id);
CREATE VIEW IF NOT EXISTS effective_routes AS SELECT * FROM routes r WHERE role!='original_audit_reference' AND inferred=0 AND NOT EXISTS(SELECT 1 FROM invalidations i WHERE i.output_id=r.route_id);
CREATE VIEW IF NOT EXISTS effective_relationships AS SELECT * FROM relationships r WHERE inferred=0 AND unresolved=0 AND invalidated=0 AND NOT EXISTS(SELECT 1 FROM invalidations i WHERE i.output_id=r.relationship_id);
CREATE VIEW IF NOT EXISTS effective_claims AS SELECT c.* FROM claims c JOIN sources s USING(source_id) WHERE c.usable=1 AND s.is_public=1 AND NOT EXISTS(SELECT 1 FROM invalidations i WHERE i.output_id=c.claim_id);
CREATE VIEW IF NOT EXISTS effective_claim_links AS SELECT l.* FROM claim_links l JOIN effective_claims c USING(claim_id) JOIN effective_routes r USING(route_id) WHERE l.usable=1;
CREATE VIEW IF NOT EXISTS effective_place_links AS SELECT l.* FROM place_links l JOIN effective_routes r USING(route_id) JOIN effective_entities e USING(entity_id) WHERE l.inferred=0 AND l.unresolved=0 AND (l.relationship_id IS NULL OR EXISTS(SELECT 1 FROM effective_relationships s WHERE s.relationship_id=l.relationship_id));
